class GitStashManager:
    def __init__(self, clean_state: dict[str, str]):
        self.base_state = dict(clean_state)
        self.stack: list[dict] = []

    def push(self, workdir: dict[str, str], message: str = '') -> int:
        delta = {}
        for k, v in workdir.items():
            if self.base_state.get(k) != v:
                delta[k] = v
        for k in self.base_state:
            if k not in workdir:
                delta[k] = None

        if not delta:
            return len(self.stack)

        entry = {
            'message': message or f'WIP on main',
            'delta': delta
        }
        self.stack.insert(0, entry)
        return len(self.stack)

    def apply(self, index: int = 0, current_workdir: dict[str, str] | None = None) -> dict[str, str]:
        if index < 0 or index >= len(self.stack):
            raise IndexError('Stash index out of range')

        target = dict(self.base_state if current_workdir is None else current_workdir)
        delta = self.stack[index]['delta']

        for path, new_val in delta.items():
            # Если целевой рабочий каталог изменен относительно базы в этом же файле
            if current_workdir is not None:
                curr_val = current_workdir.get(path)
                base_val = self.base_state.get(path)
                if curr_val != base_val and curr_val != new_val:
                    raise RuntimeError('Merge conflict on stash apply')
            if new_val is None:
                target.pop(path, None)
            else:
                target[path] = new_val
        return target

    def pop(self, index: int = 0, current_workdir: dict[str, str] | None = None) -> dict[str, str]:
        result = self.apply(index, current_workdir)
        self.drop(index)
        return result

    def drop(self, index: int = 0) -> None:
        if index < 0 or index >= len(self.stack):
            raise IndexError('Stash index out of range')
        self.stack.pop(index)

    def list_entries(self) -> list[str]:
        return [f'stash@{{{i}}}: {entry["message"]}' for i, entry in enumerate(self.stack)]

