def simulate_git_reset(target_commit_snapshot: dict[str, str], current_head: dict[str, str], current_index: dict[str, str], current_worktree: dict[str, str], mode: str = '--mixed') -> tuple[dict[str, str], dict[str, str], dict[str, str]]:
    if mode not in ('--soft', '--mixed', '--hard'):
        raise ValueError(f'Unsupported reset mode: {mode}')

    new_head = dict(target_commit_snapshot)

    if mode == '--soft':
        return new_head, dict(current_index), dict(current_worktree)

    if mode == '--mixed':
        return new_head, dict(target_commit_snapshot), dict(current_worktree)

    # mode == '--hard'
    # Вычисляем untracked файлы (которых нет ни в current_head, ни в current_index)
    untracked = {}
    for path, content in current_worktree.items():
        if path not in current_head and path not in current_index:
            untracked[path] = content

    new_worktree = dict(target_commit_snapshot)
    new_worktree.update(untracked)
    return new_head, dict(target_commit_snapshot), new_worktree

