    color = {}
    parent_map = {}
    for node in module_imports:
        color[node] = 'WHITE'

    def dfs(u, path):
        color[u] = 'GRAY'
        for v in module_imports.get(u, []):
            if v not in color:
                color[v] = 'WHITE'
            if color[v] == 'GRAY':
                # Cycle detected
