class CodeownersResolver:
    def __init__(self, codeowners_text: str):
        self.rules = []
        for line in codeowners_text.splitlines():
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split()
            if len(parts) < 2:
                continue
            pattern = parts[0]
            owners = parts[1:]
            self.rules.append((pattern, owners))

    def _matches(self, path: str, pattern: str) -> bool:
        norm_path = path.lstrip('/')
        filename = norm_path.split('/')[-1]
        p = pattern
        is_rooted = p.startswith('/')
        if is_rooted:
            p = p[1:]
        if p.endswith('/'):
            # Matches directory and any contents
            dir_prefix = p
            if is_rooted:
                return norm_path.startswith(dir_prefix) or norm_path == dir_prefix.rstrip('/')
            return norm_path.startswith(dir_prefix) or f'/{dir_prefix}' in f'/{norm_path}'
        if is_rooted:
            return fnmatch.fnmatch(norm_path, p)
        return fnmatch.fnmatch(norm_path, p) or fnmatch.fnmatch(filename, p)

    def resolve_owners_for_path(self, file_path: str) -> list[str]:
        norm_path = file_path.lstrip('/')
        matched_owners = []
        for pattern, owners in self.rules:
            if self._matches(norm_path, pattern):
