import fnmatch

class GitIgnoreMatcher:
    def __init__(self, gitignore_content: str):
        self.rules = []
        for line in gitignore_content.splitlines():
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            is_negative = False
            if line.startswith('!'):
                is_negative = True
                line = line[1:]

            dir_only = line.endswith('/')
            if dir_only:
                line = line[:-1]

            is_rooted = '/' in line.lstrip('/')
            pattern = line.lstrip('/')
            self.rules.append({
                'pattern': pattern,
                'negative': is_negative,
                'dir_only': dir_only,
                'rooted': is_rooted
            })

    def is_ignored(self, path: str, is_dir: bool = False) -> bool:
        norm_path = path.strip('/')
        parts = norm_path.split('/')

        # Проверяем предков: если любой родитель проигнорирован, путь проигнорирован
        for i in range(1, len(parts)):
            parent_path = '/'.join(parts[:i])
            if self._matches_rules(parent_path, is_dir=True):
                return True

        return self._matches_rules(norm_path, is_dir=is_dir)

    def _matches_rules(self, path: str, is_dir: bool) -> bool:
        ignored = False
        parts = path.split('/')
        filename = parts[-1]

        for r in self.rules:
            if r['dir_only'] and not is_dir:
                continue

            matched = False
            if r['rooted']:
                if fnmatch.fnmatch(path, r['pattern']):
                    matched = True
            else:
                if fnmatch.fnmatch(filename, r['pattern']) or fnmatch.fnmatch(path, r['pattern']):
                    matched = True

            if matched:
                ignored = not r['negative']
        return ignored

